STORE_FIELDS = ("require_open_cash_session", "cash_closing_tolerance", "pdv_auto_lock", "pdv_lock_minutes",
                "require_seller", "auto_print_receipt", "confirm_address_at_checkout", "ask_print_danfe",
                "print_cancellation_receipt", "scale_barcode_mode", "scale_barcode_prefix")


def _grouped(model, account, stores, values_of, link):
    """Filiais com os MESMOS valores dividem uma regra; a do 1º grupo é a padrão."""
    groups = {}
    for store in stores:
        groups.setdefault(values_of(store), []).append(store)
    default = None
    for index, (values, members) in enumerate(groups.items()):
        name = "Padrão" if index == 0 else f"Regra - {members[0].name}"[:120]
        rule = model._base_manager.create(account=account, name=name, is_default=index == 0, **dict(values))
        default = default or rule
        link(members, rule)
    return default or model._base_manager.create(account=account, name="Padrão", is_default=True)


def copy_to_rules(apps, schema_editor):
    Account = apps.get_model("starrp", "Account")
    Store = apps.get_model("starrp", "Store")
    StoreRule = apps.get_model("starrp", "StoreRule")
    LogisticsRule = apps.get_model("starrp", "LogisticsRule")
    StockRule = apps.get_model("starrp", "StockRule")
    LogisticsSettings = apps.get_model("starrp", "LogisticsSettings")
    StockSettings = apps.get_model("starrp", "StockSettings")

    for account in Account._base_manager.all():
        everyone = Store._base_manager.filter(account=account)
        alive = list(everyone.filter(deleted_at__isnull=True).order_by("created_at"))

        def link(field):
            return lambda members, rule: Store._base_manager.filter(pk__in=[m.pk for m in members]).update(**{field: rule})

        rule = _grouped(StoreRule, account, alive, lambda st: tuple((f, getattr(st, f)) for f in STORE_FIELDS), link("rule"))
        conference = {ls.store_id: ls.allow_manual_conference for ls in
                      LogisticsSettings._base_manager.filter(account=account, deleted_at__isnull=True)}
        logistics = _grouped(LogisticsRule, account, alive,
                             lambda st: (("allow_manual_conference", conference.get(st.pk, False)),), link("logistics_rule"))
        old = StockSettings._base_manager.filter(account=account, deleted_at__isnull=True).first()
        stock = StockRule._base_manager.create(account=account, name="Padrão", is_default=True, **({
            f: getattr(old, f) for f in ("picking_strategy", "expiry_warning_days", "block_expired", "allow_negative_stock")
        } if old else {}))
        everyone.update(stock_rule=stock)
        # Filial excluída também aponta para uma regra (o campo vira obrigatório).
        everyone.filter(rule__isnull=True).update(rule=rule)
        everyone.filter(logistics_rule__isnull=True).update(logistics_rule=logistics)


